/**
 * Fireteam step content in a report (4.9 review, SH-30). A fireteam deployment's `planRationale`
 * and each member's `task`, `completionReason` and `errorMessage` are the agent's own reasoning,
 * instructions and output: the fireteam's counterpart of a chain step's thought, command line and
 * error (lib/authz/stepContent.ts), raw data for a reader below `R*`.
 *
 * A report is one stored HTML file that every `reports:read` holder (R) opens, generated by
 * someone at `reports:generate` (W, which always reaches R*), so the generator's access says
 * nothing about who reads it. The report keeps these fields, the owner's report unchanged, and
 * records whether it holds any (`metrics.stepContent`); opening one that does, or one generated
 * before the record existed, needs Raw data & files.
 */
import type { ReportData } from './reportData'

export function reportHoldsStepContent(data: Pick<ReportData, 'fireteams'>): boolean {
  const filled = (value: unknown) => typeof value === 'string' && value.trim() !== ''
  return (data.fireteams?.deployments ?? []).some(d =>
    filled(d.planRationale) || d.members.some(m => filled(m.task) || filled(m.completionReason) || filled(m.errorMessage)))
}

/** Whether a stored report's metrics leave it possibly holding step content: all but an explicit `false`. */
export function reportMayHoldStepContent(metrics: unknown): boolean {
  if (!metrics || typeof metrics !== 'object') return true
  return (metrics as { stepContent?: unknown }).stepContent !== false
}
